head.script:
scwin.onpageload = function() {
    dataMap1.set("key1", $p.getFrame().getURL($p.getFrame().getSrc() || "[WMA_tabMain]" + location.origin));
    scwin.trigger1_onclick();
    scwin.trigger2_onclick();
};
scwin.onpageunload = function() {};
scwin.trigger1_onclick = function(e) {
    var id = "tab_" + scwin.cnt++;
    var tabOpt = {
        "id": id + "_tabs",
        "label": "wframe1",
        "closable": true
    };
    var contOpt = {
        "wframe": true,
        "scope": true,
        "src": "tabControl_split_WESD-873_(WSQ-4845)_WMA_wframe1.xml"
    }
    tabControl1.addTab(id, tabOpt, contOpt);
};
scwin.trigger2_onclick = function(e) {
    var id = "tab_" + scwin.cnt++;
    var tabOpt = {
        "id": id + "_tabs",
        "label": "wframe2",
        "closable": true
    };
    var contOpt = {
        "wframe": true,
        "scope": true,
        "src": "tabControl_split_WESD-873_(WSQ-4845)_WMA_wframe2.xml"
    }
    tabControl1.addTab(id, tabOpt, contOpt);
};
scwin.trigger3_onclick = function(e) {
    var id = "tab_" + scwin.cnt++;
    var tabOpt = {
        "id": id + "_tabs",
        "label": "main",
        "closable": true
    };
    var contOpt = {
        "wframe": true,
        "scope": true,
        "src": "tabControl_split_WESD-873_(WSQ-4845)_WMA_main.xml"
    }
    tabControl1.addTab(id, tabOpt, contOpt);
};
scwin.tabControl1_ontabsplit = function(tabIdx) {
    var frameObj = tabControl1.getFrame(tabIdx);
    var src = frameObj.getSrc();
    var frameId = frameObj.id;
    tabControl1.deleteTab(tabIdx);
    var options = {
        id: "popup_" + frameId,
        type: "wframePopup",
        width: "700px",
        height: "500px"
    };
    $p.openPopup(src, options);
}
scwin.simulateWrapper = function(target, type, options) {
    WebSquare.wUnit.getJq(target).simulate(type, options);
}
scwin.setSimulate1 = function() {
    scwin.simulateWrapper('#tabControl1_tab_tab_2_tabHTML', 'drag-n-drop', {
        dx: 0,
        dy: 300
    });
}
scwin.checkVal = function() {
    return WebSquare.wUnit.getDomById('popup_'+$p.id+'tabControl1_contents_tab_2_body') != null;
}
scwin.unitTest = function() {
    //Init test
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "400");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger2').click()");
    WebSquare.wUnit.addCommand("pause", "400");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger3').click()");
    WebSquare.wUnit.addCommand("pause", "400");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('tabControl1_tab_tab_2_tabHTML').click()");
    WebSquare.wUnit.addCommand("pause", "400");
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate1()");
    WebSquare.wUnit.addCommand("pause", "400");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop unit Test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    if(WebSquare._xv !== "SP5"){requires("uiplugin.popup");}
    scwin.cnt = 0;
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
